//! 内核→引擎桥 (架构 Phase 0 · 分仓规划 v2 §4 的 KbBridge 依赖倒置落点)
//!
//! chat(未来 kernel 仓)对检索引擎(kb/fable, 未来 polaris-fable 仓)与专家团
//! (expert, 未来 polaris-experts 仓)的全部依赖收口于此: chat 只认这里的 trait 与
//! Lite DTO, 不再 import 任何引擎模块 —— 抽仓时本文件随 kernel 走, 引擎实现由
//! 外壳注入(见 `crate::wiring`), 与 lib.rs 的 `KbLocator`(sandbox 板块)同一模式。
//!
//! 注入时机: 桌面 `run()` setup 与 server `serve()` 的 init 序列(均在任何命令可
//! 执行之前调用 `wiring::wire_engine_bridges()`)。未注入时优雅降级: KB 召回/家底
//! 概览/专家路由静默跳过 —— 与「未拼装该引擎」的极简形态语义一致, 不 panic。
//!
//! 性能: 桥只在**每条消息**组 prompt 时走一次量级(非逐 token 热路径), OnceLock 读
//! + 动态分发的开销为纳秒级; DTO 映射复用的都是本就要 clone 的字段, 零新增拷贝。

use std::sync::{Arc, OnceLock};

// ───────────────────────── 检索引擎桥 (kb + fable 同属未来 fable 仓, 共用一桥) ─────────────────────────

/// `kb::KbHit` 的内核侧投影: 只带 chat 实际消费的字段(score 等引擎细节不过桥)。
pub struct KbHitLite {
    pub title: String,
    pub path: String,
    pub snippet: String,
}

/// fable 混检命中的内核侧投影(标题由调用方从 path 派生, 不过桥)。
pub struct RagHitLite {
    pub path: String,
    pub snippet: String,
}

/// `kb::KbOverview` 的内核侧投影(四层家底计数)。
pub struct KbOverviewLite {
    pub root: String,
    pub wiki: usize,
    pub raw_md: usize,
    pub output: usize,
    pub memory: usize,
}

/// `fable::FableStatus` 的内核侧投影: 只带「索引就绪判定 + 家底概览」用到的三个计数。
pub struct FableStatusLite {
    pub files_total: u64,
    pub chunks_total: u64,
    pub lex_files: u64,
}

pub trait KbBridge: Send + Sync {
    /// KB 根目录(未配置返回空串, 语义同 `kb::kb_root`)。
    fn root(&self) -> String;
    /// 四层家底概览(root 为空表示 KB 未就绪)。
    fn overview(&self) -> KbOverviewLite;
    /// Karpathy 式结构化 wiki 上下文块(语义同 `kb::kb_context_block_scoped`; 空串=无内容)。
    /// claude_md 主上下文渲染用 —— kernel 侧不再 import kb。
    fn context_block_scoped(&self, scope: Option<&str>) -> String;
    /// 检索枢纽注入块(语义同 `fable::agent::fable_context_block`; 空串=未盘点)。
    fn fable_context_block(&self, full: bool) -> String;
    /// 关键词/标题检索同步核(语义同 `kb::kb_search_sync`)。
    fn search_sync(&self, query: String, top_k: Option<usize>) -> Vec<KbHitLite>;
    /// fable 索引状态(打不开 fable.db 等失败情形返回 None)。
    fn fable_status(&self) -> Option<FableStatusLite>;
    /// fable 混检(语义同 `fable::retrieve::search`); Err 折叠为 None, 由调用方走关键词兜底。
    fn rag_search(
        &self,
        query: &str,
        top_k: usize,
        mode: &str,
        scope: Option<&str>,
    ) -> Option<Vec<RagHitLite>>;
}

// ───────────────────────── 专家团桥 (expert, 未来 experts 仓) ─────────────────────────

/// 专家团对 chat 暴露的三个决策点。`ExpertMatch` 等引擎内部类型不过桥:
/// 「召集成队 + 生成分工块」在实现侧一步完成(`team_block_spawn`), 内核只拿最终注入文本。
pub trait ExpertBridge: Send + Sync {
    /// 是否为多专家任务(语义同 `expert::detect_multi_expert_task`)。
    fn detect_multi_expert_task(&self, prompt: &str) -> bool;
    /// 召集专家团并生成分工注入块(组合 `expert_team_spawn` + `team_block`)。
    fn team_block_spawn(&self, project_id: String, prompt: String) -> Option<String>;
    /// 智能匹配单/少量专家的视角注入块(语义同 `expert::route_block`)。
    fn route_block(&self, prompt: &str) -> Option<String>;
}

// ───────────────────────── 注入点 ─────────────────────────

static KB_BRIDGE: OnceLock<Arc<dyn KbBridge>> = OnceLock::new();
static EXPERT_BRIDGE: OnceLock<Arc<dyn ExpertBridge>> = OnceLock::new();

/// 外壳启动时注入检索引擎实现(重复注入被忽略, 幂等)。
pub fn set_kb_bridge(b: Arc<dyn KbBridge>) {
    let _ = KB_BRIDGE.set(b);
}

/// 外壳启动时注入专家团实现(重复注入被忽略, 幂等)。
pub fn set_expert_bridge(b: Arc<dyn ExpertBridge>) {
    let _ = EXPERT_BRIDGE.set(b);
}

pub(crate) fn kb_bridge() -> Option<&'static Arc<dyn KbBridge>> {
    KB_BRIDGE.get()
}

pub(crate) fn expert_bridge() -> Option<&'static Arc<dyn ExpertBridge>> {
    EXPERT_BRIDGE.get()
}
//! 对话核心的 serde 类型: 命令入参 / 流事件。
//! (从 chat.rs 纯移动拆出, 逻辑零变化)

use serde::{Deserialize, Serialize};

// ───────────────────────── Types ─────────────────────────

#[derive(Debug, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum PermissionMode {
    Manual,
    AutoCurrent,
    AutoAll,
    Deny,
}

impl PermissionMode {
    pub(crate) fn cli_value(&self) -> &'static str {
        match self {
            PermissionMode::Manual => "default",
            PermissionMode::AutoCurrent => "acceptEdits",
            // AutoAll = 终端裸跑 claude --dangerously-skip-permissions 的同款体验:
            // 全工具免确认(headless 下 acceptEdits 只批文件编辑, 白名单外的工具
            // 一律被拒 → 与 CLI 体验割裂)。用户显式选这一档即知情放行。
            PermissionMode::AutoAll => "bypassPermissions",
            PermissionMode::Deny => "plan",
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ChatSendArgs {
    pub prompt: String,
    /// Explicit uploaded images; prompt paths remain available to legacy tools.
    #[serde(default)]
    pub image_paths: Option<Vec<String>>,
    /// Pi thinking level; omitted values keep the daemon's default/current level.
    #[serde(default)]
    pub thinking_level: Option<String>,
    pub permission_mode: PermissionMode,
    #[serde(default)]
    pub use_sandbox: bool,
    #[serde(default)]
    pub skill_ids: Option<Vec<String>>,
    #[serde(default)]
    pub conversation_id: Option<String>,
    /// 目标模式：完成条件。设置后注入「持续推进直到达成」指令。
    #[serde(default)]
    pub goal: Option<String>,
    /// 「动态编排」：把本轮当成多智能体编排——编排器拆成 N 个独立子任务，
    /// 用 Task 子代理并行扇出，每条流水线 实现→对抗式校验→修复，最后汇总。
    #[serde(default)]
    pub dynamic_workflow: bool,
    /// 「知识库严格搜索」：打开时才把 KB 结构化 wiki + 双链地图注入上下文。
    /// 默认 false 以节省 token，日常任务不注入大段 KB 导航。
    #[serde(default)]
    pub use_kb: bool,
    /// 「分批长任务」：把一次超长生成(如 60 页 PPT)拆成多轮有界批次。
    /// 注入分批构建协议——先产 `polaris.build.json` 计划清单, 每轮只建 ≤batch_size 个
    /// pending 单元并回写状态; 由前端编排循环驱动多轮、断线从清单下一个 pending 续跑。
    /// 缘由: 单轮把 60 页全吐完会让流式连接跑太久被掐(socket closed → exit 1), 分批让
    /// 每轮输出有界、context 不随页数膨胀、崩了也不丢已落盘的批次。
    #[serde(default)]
    pub batch_build: bool,
    /// 每批最多构建几个单元(页/章/文件)。None 时用默认值。
    #[serde(default)]
    pub batch_size: Option<usize>,
    /// 智能体模式: "single" | "expert-team" | "auto-match"
    /// 专家团模式下自动检测任务复杂度，必要时注入多专家召集信息。
    #[serde(default)]
    pub agent_mode: Option<String>,
    /// 工作模式: "fast"(默认·快速) | "work"(工作·纯 Claude Code)。
    /// - 快速模式: 强制快速调用知识库(快档召回, 跳重排 ~1.8s→~0.25s)+ 快速回答; 工具精简
    ///   (弃 Task/NotebookEdit)、提示词瘦身(跳「可运行项目」「长任务」约定)、上下文预算调小、
    ///   权限默认自动批准 —— 一切为「秒级查库 + 秒级回答」。
    /// - 工作模式: 纯 Claude Code —— 放开全套工具、注入全部约定(可运行项目/长任务)、KB 召回走
    ///   全质量 hybrid(带重排), 面向写代码/跑项目/产出复杂成品。
    /// None 视为 fast —— 不带此字段的旧调用方(如分批长任务)默认走快速预设。
    #[serde(default)]
    pub work_mode: Option<String>,
    /// 本对话选定的供应商 id(来自左下角「API 供应商」中心, 自动识别已配的那些)。
    /// None / "" / "auto" = Auto 档(沿用应用全局当前供应商)。具体 id = 本对话钉死这家,
    /// 逐命令注入其 env 实现「每个对话各用各的 API」真隔离, 与全局开关、其它并发对话解耦。
    #[serde(default)]
    pub provider_id: Option<String>,
}

/// chat_prewarm(预热常驻 claude 进程)的入参: 只带**会进指纹**的那几项设置。
/// 与 ChatSendArgs 分开: 预热发生在用户还没写出 prompt 时, prompt 相关字段
/// (skill/goal/批量等)都还不存在; 预热只需算出与真发送一致的进程指纹。
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ChatPrewarmArgs {
    pub conversation_id: String,
    /// None = 按工作模式套前端同款默认(work=手动/fast=自动批准, 见 ChatComposer
    /// applyModeDefaults) —— 保证「切对话即预热」这种拿不到输入区状态的触发点,
    /// 算出的指纹与随后真发送大概率一致, 预热才不白做。
    #[serde(default)]
    pub permission_mode: Option<PermissionMode>,
//! 外壳拼装点 (架构 Phase 0 · 分仓规划 v2): 把各引擎的具体实现注入内核桥
//! (`chat::bridges`)。桌面 `run()` setup 与 server `serve()` 都在 init 序列里调用
//! `wire_engine_bridges()` —— 这是全 crate 里唯一同时认识「内核桥 trait」与
//! 「引擎具体实现」的地方; 抽仓后本文件留在组装壳(polaris-app), 引擎换实现只改这里。

use std::sync::Arc;

use crate::chat::bridges::{
    self, ExpertBridge, FableStatusLite, KbBridge, KbHitLite, KbOverviewLite, RagHitLite,
};

/// 检索引擎桥的官方实现: 直连 kb(妈妈库/关键词) + fable(盘点/混检)。
struct ShellKbBridge;

impl KbBridge for ShellKbBridge {
    fn root(&self) -> String {
        crate::kb::kb_root()
    }

    fn overview(&self) -> KbOverviewLite {
        let ov = crate::kb::kb_overview();
        KbOverviewLite {
            root: ov.root,
            wiki: ov.wiki,
            raw_md: ov.raw_md,
            output: ov.output,
            memory: ov.memory,
        }
    }

    fn context_block_scoped(&self, scope: Option<&str>) -> String {
        crate::kb::kb_context_block_scoped(scope)
    }

    fn fable_context_block(&self, full: bool) -> String {
        crate::fable::agent::fable_context_block(full)
    }

    fn search_sync(&self, query: String, top_k: Option<usize>) -> Vec<KbHitLite> {
        crate::kb::kb_search_sync(query, top_k)
            .into_iter()
            .map(|h| KbHitLite {
                title: h.title,
                path: h.path,
                snippet: h.snippet,
            })
            .collect()
    }

    fn fable_status(&self) -> Option<FableStatusLite> {
        crate::fable::status().ok().map(|s| FableStatusLite {
            files_total: s.files_total,
            chunks_total: s.chunks_total,
            lex_files: s.lex_files,
        })
    }

    fn rag_search(
        &self,
        query: &str,
        top_k: usize,
        mode: &str,
        scope: Option<&str>,
    ) -> Option<Vec<RagHitLite>> {
        crate::fable::retrieve::search(query, top_k, mode, scope)
            .ok()
            .map(|r| {
                r.hits
                    .into_iter()
                    .map(|h| RagHitLite {
                        path: h.path,
                        snippet: h.snippet,
                    })
                    .collect()
            })
    }
}

/// 专家团桥的官方实现: 直连 expert 花名册/路由/召集。
struct ShellExpertBridge;

impl ExpertBridge for ShellExpertBridge {
    fn detect_multi_expert_task(&self, prompt: &str) -> bool {
        crate::expert::detect_multi_expert_task(prompt)
    }

    fn team_block_spawn(&self, project_id: String, prompt: String) -> Option<String> {
        let matches = crate::expert::expert_team_spawn(project_id, prompt);
        crate::expert::team_block(&matches)
    }

    fn route_block(&self, prompt: &str) -> Option<String> {
        crate::expert::route_block(prompt)
    }
}

/// 把官方引擎实现注入内核桥。幂等(重复调用被 OnceLock 忽略), 开销一次性。
pub fn wire_engine_bridges() {
    bridges::set_kb_bridge(Arc::new(ShellKbBridge));
    bridges::set_expert_bridge(Arc::new(ShellExpertBridge));
    if let (Some(dirs), Ok(config)) = (directories::UserDirs::new(), crate::chat::backend::config::Config::load()) {
        crate::chat::backend::host_tools::set_sandbox_executor(Arc::new(
            crate::chat::backend::docker_tools::ManagedSandbox {
                container: config.agentd.sandbox_container,
                protected_paths: vec![dirs.home_dir().join("Polaris/data"),
                    dirs.home_dir().join(".polaris"), dirs.home_dir().join(".pi"),
                    dirs.home_dir().join(".claude"), dirs.home_dir().join(".codex"),
                    dirs.home_dir().join(".ssh"), dirs.home_dir().join(".aws")],
            },
        ));
    }
}

