pub struct ResolvedMount { pub source: PathBuf, pub destination: String, pub read_only: bool }
impl Config {
    pub fn resolve_mounts(&self, project: &Path, kb: &Path, home: &Path) -> Result<Vec<ResolvedMount>> {
        self.validate()?;
